import React, { useState } from "react";
import Header from "./components/header";
import Home from "./pages/home";
import Stall from "./pages/stall"; // 1. Imported the Stall component
import Footer from "./components/footer";

const WebApp = () => {
    const [darkMode, setDarkMode] = useState(false);
    // Simple state to toggle between Home and the Virtual Stall
    const [view, setView] = useState("home");

    return React.createElement("div", {
        className: `${darkMode ? "bg-gray-900 text-white" : "bg-gray-50 text-gray-900"
            } min-h-screen transition-colors duration-500 font-sans`
    },
        React.createElement(Header, { darkMode: darkMode, setDarkMode: setDarkMode }),

        /* 2. Logic to switch views */
        view === "home"
            ? React.createElement(Home, { darkMode: darkMode, onEnterStall: () => setView("stall") })
            : React.createElement(Stall, { onBack: () => setView("home") }),

        React.createElement(Footer, null)
    );
};

export default WebApp;
